sources.orbital-greenhouse.json:
{
  "specVersion": "0.2.0-draft.2",
  "kind": "scenario",
  "id": "scenario:spatial",
  "resources": {
    "character:aya": {
      "path": "characters/aya.simkind.json"
    },
    "character:mira": {
      "path": "characters/mira.simkind.json"
    },
    "character:sol": {
      "path": "characters/sol.simkind.json"
    },
    "catalog:spatial": {
      "path": "tools/spatial.json"
    }
  },
  "host": {
    "contractId": "example.spatial",
    "version": "1.0.0"
  },
  "cast": [
    {
      "instanceId": "simkin:aya",
      "characterRef": "character:aya",
      "allowedTools": [
        "move",
        "say"
      ]
    },
    {
      "instanceId": "simkin:mira",
      "characterRef": "character:mira",
      "allowedTools": [
        "move",
        "say"
      ]
    },
    {
      "instanceId": "simkin:sol",
      "characterRef": "character:sol",
      "allowedTools": [
        "move",
        "say"
      ]
    }
  ],
  "toolCatalogRef": "catalog:spatial",
  "initialConditions": {
    "sharedContext": "Three survey drones reach a derelict orbital greenhouse. Choose how to explore, share observations, and decide where to gather. No required route or agreement. World coordinates are in metres, Y up.",
    "positions": {
      "simkin:aya": [
        -4,
        0,
        0
      ],
      "simkin:mira": [
        4,
        0,
        0
      ],
      "simkin:sol": [
        0,
        3,
        4
      ]
    },
    "speed": 1,
    "bound": 12,
    "obstacles": [
      {
        "center": [
          0,
          0,
          0
        ],
        "radius": 1.5
      }
    ]
  },
  "recommendations": {
    "features": {
      "simkind.memory-retrieval": {
        "config": {
          "maxItems": 6
        }
      }
    }
  }
}

sources.tools/spatial.json:
{
  "specVersion": "0.2.0-draft.2",
  "kind": "tool-catalog",
  "id": "catalog:spatial",
  "host": {
    "contractId": "example.spatial",
    "version": "1.0.0"
  },
  "tools": [
    {
      "id": "move",
      "version": "1.0.0",
      "description": "Fly to a 3D position in frame:world (metres, Y up). Motion takes time; solid obstacles block the swept path. Cancellation keeps the reached position.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "position",
          "frameId"
        ],
        "properties": {
          "position": {
            "type": "array",
            "minItems": 3,
            "maxItems": 3,
            "items": {
              "type": "number",
              "minimum": -1000,
              "maximum": 1000
            }
          },
          "frameId": {
            "const": "frame:world"
          }
        }
      },
      "lifecycle": {
        "asynchronous": true,
        "cancellable": true
      }
    },
    {
      "id": "say",
      "version": "1.0.0",
      "description": "Broadcast text to the other participants. Claims do not move bodies.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "text"
        ],
        "properties": {
          "text": {
            "type": "string",
            "maxLength": 4000
          }
        }
      },
      "lifecycle": {
        "asynchronous": false,
        "cancellable": false
      }
    }
  ]
}
